a=JSON.parse(java.ajax('https://app.jjwxc.org/androidapi/getnovelOtherInfo?novelId='+java.get('id')+'&type=novelbasicinfo&versionCode=148'));
b=a.novelLeave;
c=JSON.parse(result);
z=s=>s.length>3?s:'';
['',b.leaveDateBack,b.leaveContent,b.leaveDate,'🔖 '+c.novelIntroShort,'​','标签：'+c.novelTags,z(c.protagonist),z(c.costar),z(c.other),'风格：'+c.novelStyle+'　　视角：'+c.mainview,'收藏：'+a.novelbefavoritedcount+'　评论：'+c.comment_count+'　评分：'+c.novelReviewScore,'┄┄',c.novelIntro].join('\n').replace('立意:','┄┄\n立意：').replace('评分：\n','\n').replace('🔖 \n','')

ruleSearch.lastChapter:
@js:
last=JSON.parse(java.ajax('https://android.jjwxc.net/androidapi/chapterList?novelId='+java.get('id'))).chapterlist;
if(last){
last=last[last.length-1];
vip=last.isvip!=0?"💰":'';
date=last.chapterdate;
chapter=last.chaptername;
chapterid=last.chapterid;
result=vip+chapterid+'、'+chapter+'  '+date}

ruleToc.chapterUrl:
@js:
$=result;
cookie=java.getCookie("https://m.jjwxc.net","sid");
