        "sessionid"
      )
    ) ? String(
     cookie.getKey(
        "fanqienovel.com", 
        "sessionid"
      )
    ) : (
     source.getLoginInfoMap()
      ? source.getLoginInfoMap()
      : {}
    )['手动登录Token']
  )
  java.toast("登录Token已打印到日志，请妥善保管")
